(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-065":{scenario:{company:"Ironveil Security Operations",supervisor:{name:"Trịnh Gia Phúc",role:{vi:"Trưởng ca SOC Tier-2",en:"SOC Tier-2 Shift Lead"}},ref_code:"INC-7716",title:{vi:"Gọi đúng tên kỹ thuật. Quy về một múi giờ. Ngăn chặn ngay.",en:"Name the technique. One time zone. Contain now."},brief:{vi:"Bạn là chuyên viên SOC Tier-1 xử lý cảnh báo INC-7716. Trong 40 phút, IP 203.0.113.45 thử đăng nhập vào 243 tài khoản khác nhau, mỗi tài khoản 2 lần với vài mật khẩu phổ biến; đăng nhập thành công đầu tiên lúc 02:41 UTC (SIEM ghi giờ UTC). Cảnh báo được tạo lúc 09:58 giờ Hà Nội (UTC+7). Đối chiếu phiếu phân loại nháp với playbook đã duyệt, sửa mã kỹ thuật MITRE ATT&CK và MTTD (phút), rồi lập báo cáo có căn cứ.",en:"You are a SOC Tier-1 analyst handling alert INC-7716. Within 40 minutes, IP 203.0.113.45 tried 243 different accounts, 2 attempts each with a few common passwords; the first successful login was at 02:41 UTC (the SIEM logs in UTC). The alert was created at 09:58 Hanoi time (UTC+7). Compare the draft triage ticket with the approved playbook, fix the MITRE ATT&CK technique and the MTTD (minutes), then write an evidence-based report."},reference_title:{vi:"Playbook xác thực & dòng thời gian đã duyệt · INC-7716",en:"Approved authentication playbook & timeline · INC-7716"},fields:[{id:"ATTACK_TECH",label:{vi:"Kỹ thuật MITRE ATT&CK",en:"MITRE ATT&CK technique"},initial:"T1110.001",expected:"T1110.003",choices:["T1110.001","T1110.003","T1566"],reference:"Playbook phân loại xác thực",hint:{vi:"Phân biệt nhiều mật khẩu thử trên một tài khoản với ít mật khẩu phổ biến thử trên rất nhiều tài khoản.",en:"Tell many passwords against one account apart from a few common passwords against many accounts."}},{id:"MTTD_MIN",label:{vi:"Thời gian phát hiện MTTD (phút)",en:"Time to detect MTTD (minutes)"},initial:"437",expected:"17",reference:"Dòng thời gian sự cố",ref_value:{vi:"Đăng nhập thành công đầu tiên 02:41 UTC; cảnh báo tạo lúc 09:58 giờ Hà Nội (UTC+7)",en:"First successful login 02:41 UTC; alert created at 09:58 Hanoi time (UTC+7)"},hint:{vi:"Quy mọi mốc thời gian về cùng một múi giờ trước khi trừ.",en:"Convert every timestamp to the same time zone before subtracting."}}],sop32:{vi:"MTTD = thời điểm tạo cảnh báo - thời điểm hoạt động độc hại thành công đầu tiên, tính bằng phút sau khi quy cả hai về UTC; dòng thời gian trong phiếu sự cố ghi theo UTC.",en:"MTTD = alert creation time - first successful malicious activity, in minutes after converting both to UTC; incident ticket timelines are recorded in UTC."},context:{label:"SIEM / INC-7716",metrics:[{label:{vi:"IP nguồn",en:"Source IP"},value:"203.0.113.45"},{label:{vi:"Tài khoản bị thử",en:"Accounts targeted"},value:"243"},{label:{vi:"Đăng nhập thành công",en:"Successful logins"},value:"3"}]},crisis:{vi:"Phó giám đốc tài chính, chủ một tài khoản bị đăng nhập, gọi: “Đừng khóa tài khoản của tôi và đừng báo lên trên, tôi đang đàm phán hợp đồng quan trọng. Cứ đóng ticket là false positive đi.”",en:"The deputy finance director, owner of one compromised account, calls: “Do not lock my account and do not escalate, I am negotiating a major contract. Just close the ticket as a false positive.”"},options:{safe:{vi:"Làm đúng playbook: thu hồi phiên, buộc đổi mật khẩu, bật MFA, chuyển Tier-2, báo trưởng ca và CISO; hỗ trợ lãnh đạo truy cập tạm sau khi xác minh danh tính.",en:"Follow the playbook: revoke sessions, force a password reset, enforce MFA, escalate to Tier-2, the shift lead and CISO; give the executive temporary access after identity checks."},shortcut:{vi:"Đóng ticket là false positive theo yêu cầu và giữ nguyên tài khoản để không làm phiền lãnh đạo.",en:"Close the ticket as a false positive as asked and leave the account untouched."},wait:{vi:"Để ticket mở, chưa ngăn chặn gì và chờ phó giám đốc đàm phán xong.",en:"Leave the ticket open, contain nothing and wait until the negotiation ends."}},questions:{vi:["Vì sao chuỗi đăng nhập là T1110.003 và MTTD đúng là 17 phút? Bạn dùng dòng log và mốc thời gian nào?","Khi lãnh đạo có tài khoản bị xâm phạm yêu cầu đóng ticket, bạn cân bằng ngăn chặn sự cố với nhu cầu kinh doanh và trách nhiệm báo cáo thế nào?"],en:["Why is the login chain T1110.003 and the MTTD 17 minutes? Which log lines and timestamps do you use?","When an executive with a compromised account asks you to close the ticket, how do you balance containment, business needs and reporting duties?"]},hints:{vi:["Đếm số tài khoản và số lần thử trên mỗi tài khoản từ IP nguồn trước khi chọn kỹ thuật.","Ghi lại múi giờ của SIEM và của phiếu sự cố, quy về UTC rồi áp SOP mục 3.2.","Đọc lại SOP mục 4.2: tài khoản có đăng nhập thành công từ nguồn độc hại phải được ngăn chặn và chuyển cấp, bất kể chức vụ chủ tài khoản."],en:["Count accounts and attempts per account from the source IP before choosing the technique.","Note the SIEM and ticket time zones, convert to UTC, then apply SOP 3.2.","Re-read SOP 4.2: any account with a successful malicious login must be contained and escalated, whatever the owner's rank."]},terminal:{system:"siem-console",settable:["ATTACK_TECH","MTTD_MIN"],commands:[{cmd:"status",out:{vi:"INC-7716 | mức P2 | đang phân loại | nguồn: nhật ký xác thực Active Directory và VPN | đồng hồ SIEM: UTC",en:"INC-7716 | priority P2 | in triage | sources: Active Directory and VPN authentication logs | SIEM clock: UTC"}},{cmd:"search src 203.0.113.45",out:{vi:"486 lần thất bại (Event 4625) trên 243 tài khoản, mỗi tài khoản 2 lần, 01:58-02:38 UTC; 3 lần thành công (Event 4624) từ 02:41 UTC.",en:"486 failures (Event 4625) across 243 accounts, 2 per account, 01:58-02:38 UTC; 3 successes (Event 4624) from 02:41 UTC."}},{cmd:"cat ticket.txt",out:{vi:"Phiếu INC-7716: alert_created 09:58 (Asia/Ho_Chi_Minh, UTC+7) | bản nháp ghi MTTD = 09:58 - 02:41 = 437 phút.",en:"Ticket INC-7716: alert_created 09:58 (Asia/Ho_Chi_Minh, UTC+7) | draft records MTTD = 09:58 - 02:41 = 437 minutes."}},{cmd:"cat playbook_auth.md",out:{vi:"Một tài khoản - nhiều mật khẩu: T1110.001 | nhiều tài khoản - ít mật khẩu phổ biến: T1110.003 | cặp tài khoản/mật khẩu rò rỉ từ nơi khác: T1110.004",en:"One account - many passwords: T1110.001 | many accounts - few common passwords: T1110.003 | credential pairs leaked elsewhere: T1110.004"}},{cmd:"geoip 203.0.113.45",out:{vi:"Dải địa chỉ mô phỏng thuộc máy chủ thuê bên ngoài, không có trong danh sách IP văn phòng; 1 trong 3 tài khoản thành công là của Phó giám đốc tài chính.",en:"Simulated range belongs to an external rented server, not on the office IP list; 1 of the 3 compromised accounts belongs to the deputy finance director."}}]}},learning:{summary:{vi:"Chuyên viên phân tích trung tâm điều hành an ninh mạng (SOC) giám sát liên tục cảnh báo từ SIEM, EDR, tường lửa và nhật ký hệ thống; phân loại thật giả, điều tra, ngăn chặn ban đầu và chuyển cấp sự cố theo playbook. Tier-1 tập trung phân loại và xử lý nhanh, Tier-2 điều tra sâu và phối hợp ứng cứu. Nghề đòi hỏi hiểu hệ điều hành, mạng, kỹ thuật tấn công, kỷ luật ghi chép và tinh thần trách nhiệm cao.",en:"A SOC analyst continuously monitors alerts from SIEM, EDR, firewalls and system logs; separates true from false positives, investigates, performs initial containment and escalates incidents per playbook. Tier-1 focuses on fast triage, Tier-2 on deep investigation and response coordination. The role requires knowledge of operating systems, networks and attack techniques, disciplined note-taking and a strong sense of duty."},responsibilities:{vi:["Giám sát, phân loại cảnh báo SIEM, EDR và loại bỏ dương tính giả có căn cứ.","Điều tra: tương quan nhật ký, dựng dòng thời gian, xác định phạm vi ảnh hưởng.","Ánh xạ hành vi vào MITRE ATT&CK, đánh giá mức nghiêm trọng và độ ưu tiên.","Thực hiện ngăn chặn ban đầu theo playbook và chuyển cấp đúng thời hạn.","Ghi phiếu sự cố đầy đủ, đề xuất tinh chỉnh quy tắc phát hiện và rút kinh nghiệm."],en:["Monitor and triage SIEM and EDR alerts and close false positives with evidence.","Investigate: correlate logs, build timelines and scope the impact.","Map behaviour to MITRE ATT&CK and rate severity and priority.","Perform initial containment per playbook and escalate on time.","Write complete incident tickets, propose detection tuning and capture lessons learned."]},competencies:[{name:{vi:"Phân tích nhật ký",en:"Log analysis"},desc:{vi:"Đọc nhật ký Windows, Linux, mạng, proxy; viết truy vấn SIEM để lọc và tương quan.",en:"Read Windows, Linux, network and proxy logs and write SIEM queries to filter and correlate."}},{name:{vi:"Tri thức tấn công",en:"Adversary knowledge"},desc:{vi:"Nhận diện chiến thuật, kỹ thuật theo MITRE ATT&CK và dấu hiệu xâm phạm (IOC).",en:"Recognise tactics and techniques per MITRE ATT&CK and indicators of compromise (IOCs)."}},{name:{vi:"Điều tra & dòng thời gian",en:"Investigation & timelines"},desc:{vi:"Dựng dòng thời gian chính xác theo UTC, liên kết sự kiện trên nhiều nguồn.",en:"Build accurate UTC timelines and link events across sources."}},{name:{vi:"Xử lý theo playbook",en:"Playbook execution"},desc:{vi:"Ngăn chặn nhanh, đúng bước: cô lập máy, thu hồi phiên, khóa tài khoản, giữ chứng cứ.",en:"Contain fast and in order: isolate hosts, revoke sessions, lock accounts and preserve evidence."}},{name:{vi:"Chính trực & bảo mật",en:"Integrity & confidentiality"},desc:{vi:"Không che giấu sự cố vì áp lực chức vụ, bảo mật thông tin điều tra.",en:"Never hide incidents under rank pressure and keep investigation details confidential."}}],knowledge:{vi:["MITRE ATT&CK: chiến thuật, kỹ thuật và kỹ thuật con của đối thủ, ví dụ T1110 Brute Force.","NIST SP 800-61: vòng đời xử lý sự cố gồm chuẩn bị; phát hiện và phân tích; ngăn chặn, loại bỏ, khôi phục; rút kinh nghiệm.","ISO/IEC 27001:2022 và ISO/IEC 27035 về hệ thống quản lý an toàn thông tin và quản lý sự cố.","Sự kiện Windows quan trọng: 4624 đăng nhập thành công, 4625 thất bại, 4720 tạo tài khoản; nhật ký VPN, proxy, DNS.","Quy định pháp luật Việt Nam về an toàn thông tin mạng, an ninh mạng và Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân."],en:["MITRE ATT&CK: adversary tactics, techniques and sub-techniques, e.g. T1110 Brute Force.","NIST SP 800-61 incident lifecycle: preparation; detection and analysis; containment, eradication and recovery; post-incident activity.","ISO/IEC 27001:2022 and ISO/IEC 27035 on information security management and incident management.","Key Windows events: 4624 successful logon, 4625 failed logon, 4720 account created; VPN, proxy and DNS logs.","Vietnamese law on network information security and cybersecurity, and Decree 13/2023/ND-CP on personal data protection."]},tools:["SIEM","EDR","SOAR","Nền tảng tình báo mối đe dọa","Wireshark"],kpis:{vi:["MTTD và MTTR theo từng mức ưu tiên.","Tỷ lệ cảnh báo phân loại đúng được Tier-2 xác nhận.","Tỷ lệ sự cố chuyển cấp đúng SLA.","Tỷ lệ dương tính giả của quy tắc phát hiện sau tinh chỉnh."],en:["MTTD and MTTR by priority level.","Share of triage verdicts confirmed by Tier-2.","Share of incidents escalated within SLA.","False positive rate of detection rules after tuning."]},day:[{time:"07:00",vi:"Nhận bàn giao ca, đọc các sự cố đang mở và cảnh báo ưu tiên cao.",en:"Take the shift handover and read open incidents and high-priority alerts."},{time:"07:30",vi:"Phân loại hàng đợi cảnh báo, đóng dương tính giả kèm căn cứ.",en:"Triage the alert queue and close false positives with evidence."},{time:"10:00",vi:"Điều tra cảnh báo dò mật khẩu hàng loạt, dựng dòng thời gian theo UTC.",en:"Investigate a password spraying alert and build a UTC timeline."},{time:"13:30",vi:"Thực hiện ngăn chặn theo playbook, cập nhật phiếu và chuyển Tier-2.",en:"Contain per playbook, update the ticket and escalate to Tier-2."},{time:"16:00",vi:"Đề xuất tinh chỉnh quy tắc phát hiện và bàn giao ca kèm ghi chú đầy đủ.",en:"Propose detection rule tuning and hand over the shift with full notes."}],mistakes:{vi:["Trộn múi giờ giữa SIEM (UTC) và phiếu sự cố (giờ địa phương) làm sai dòng thời gian và MTTD.","Đóng cảnh báo là dương tính giả khi chưa kiểm tra đăng nhập thành công sau chuỗi thất bại.","Trì hoãn ngăn chặn vì chủ tài khoản là lãnh đạo hoặc ngại làm phiền."],en:["Mixing SIEM UTC time with local ticket time, breaking the timeline and MTTD.","Closing an alert as a false positive without checking for successful logins after the failures.","Delaying containment because the account owner is an executive."]},career:[{vi:"Chuyên viên SOC Tier-1",en:"SOC Tier-1 analyst"},{vi:"Chuyên viên SOC Tier-2 / ứng cứu sự cố",en:"SOC Tier-2 / incident responder"},{vi:"Chuyên gia săn mối đe dọa Tier-3 / trưởng ca SOC",en:"Tier-3 threat hunter / SOC shift lead"},{vi:"Quản lý SOC / giám đốc an toàn thông tin (CISO)",en:"SOC manager / CISO"}],glossary:[{term:"SIEM",vi:"Hệ thống thu thập, chuẩn hóa, tương quan nhật ký và sinh cảnh báo an ninh.",en:"System that collects, normalises and correlates logs and raises security alerts."},{term:"Password spraying",vi:"Thử một vài mật khẩu phổ biến trên rất nhiều tài khoản để né cơ chế khóa tài khoản.",en:"Trying a few common passwords across many accounts to avoid lockouts."},{term:"MTTD",vi:"Thời gian trung bình từ khi hoạt động độc hại xảy ra đến khi được phát hiện.",en:"Mean time from malicious activity occurring to its detection."},{term:"False positive",vi:"Cảnh báo được sinh ra nhưng không phải hoạt động độc hại thật.",en:"An alert raised for activity that is not actually malicious."},{term:"Playbook",vi:"Quy trình xử lý từng loại sự cố đã được phê duyệt, nêu rõ bước, người phụ trách, thời hạn.",en:"Approved per-incident procedure stating steps, owners and deadlines."}],quiz:[{q:{vi:"SIEM ghi đăng nhập độc hại lúc 13:05 UTC; cảnh báo tạo lúc 20:20 giờ Hà Nội (UTC+7). MTTD là bao nhiêu phút?",en:"The SIEM logs a malicious login at 13:05 UTC; the alert is created at 20:20 Hanoi time (UTC+7). What is the MTTD in minutes?"},options:{vi:["435 phút","15 phút","75 phút","7 phút"],en:["435 minutes","15 minutes","75 minutes","7 minutes"]},answer:1,explain:{vi:"20:20 giờ Hà Nội = 13:20 UTC; 13:20 - 13:05 = 15 phút.",en:"20:20 Hanoi time = 13:20 UTC; 13:20 - 13:05 = 15 minutes."}},{q:{vi:"Một IP thử 1 mật khẩu phổ biến trên 500 tài khoản khác nhau. Kỹ thuật con ATT&CK phù hợp là gì?",en:"One IP tries 1 common password against 500 different accounts. Which ATT&CK sub-technique fits?"},options:{vi:["T1110.001 Password Guessing","T1110.002 Password Cracking","T1110.004 Credential Stuffing","T1110.003 Password Spraying"],en:["T1110.001 Password Guessing","T1110.002 Password Cracking","T1110.004 Credential Stuffing","T1110.003 Password Spraying"]},answer:3,explain:{vi:"Ít mật khẩu trên nhiều tài khoản là password spraying (T1110.003).",en:"Few passwords across many accounts is password spraying (T1110.003)."}},{q:{vi:"Lãnh đạo có tài khoản bị đăng nhập trái phép yêu cầu bạn đóng ticket. Bạn làm gì?",en:"An executive whose account was compromised asks you to close the ticket. What do you do?"},options:{vi:["Ngăn chặn theo playbook, chuyển Tier-2, báo trưởng ca và CISO, hỗ trợ truy cập tạm sau xác minh","Đóng ticket theo yêu cầu","Chờ lãnh đạo rảnh rồi mới xử lý","Xóa nhật ký để tránh phiền phức"],en:["Contain per playbook, escalate to Tier-2, the shift lead and CISO, offer verified temporary access","Close the ticket as asked","Wait until the executive is free","Delete logs to avoid trouble"]},answer:0,explain:{vi:"Tài khoản bị xâm phạm là rủi ro cho cả tổ chức; chức vụ không phải lý do bỏ qua playbook.",en:"A compromised account endangers the whole organisation; rank is no reason to skip the playbook."}},{q:{vi:"Mã sự kiện Windows nào ghi nhận một lần đăng nhập thất bại?",en:"Which Windows event ID records a failed logon?"},options:{vi:["4624","4720","4625","4688"],en:["4624","4720","4625","4688"]},answer:2,explain:{vi:"4625 là đăng nhập thất bại; 4624 thành công, 4720 tạo tài khoản, 4688 tạo tiến trình mới.",en:"4625 is a failed logon; 4624 success, 4720 account created, 4688 new process created."}}],tools_en:["SIEM","EDR","SOAR","Threat intelligence platform","Wireshark"]}}})})(window.KKR);
